from copy import deepcopy


def update_registry(records, operations):
    if not isinstance(records, list) or not isinstance(operations, list):
        raise ValueError("arguments must be lists")

    def validate_record(record):
        if not isinstance(record, dict) or set(record) != {"id", "label", "level", "cohort"}:
            raise ValueError("invalid record")
        if not isinstance(record["id"], str) or not record["id"]:
            raise ValueError("invalid id")
        if not isinstance(record["label"], str) or not record["label"]:
            raise ValueError("invalid label")
        if type(record["level"]) is not int or record["level"] < 0:
            raise ValueError("invalid level")
        if not isinstance(record["cohort"], str):
            raise ValueError("invalid cohort")

    working = deepcopy(records)
    seen = set()
    for record in working:
        validate_record(record)
        if record["id"] in seen:
            raise ValueError("duplicate id")
        seen.add(record["id"])

    for operation in operations:
        if not isinstance(operation, dict) or "action" not in operation:
            raise ValueError("invalid operation")
        action = operation["action"]
        positions = {record["id"]: i for i, record in enumerate(working)}
        if action == "add":
            if set(operation) != {"action", "record"}:
                raise ValueError("invalid add")
            record = deepcopy(operation["record"])
            validate_record(record)
            if record["id"] in positions:
                raise ValueError("duplicate id")
            working.append(record)
        elif action == "change":
            allowed = {"action", "id", "label", "level", "cohort"}
            if not set(operation) <= allowed or not {"action", "id"} <= set(operation) or len(operation) < 3:
                raise ValueError("invalid change")
            record_id = operation["id"]
            if record_id not in positions:
                raise ValueError("missing id")
            updated = deepcopy(working[positions[record_id]])
            for field in ("label", "level", "cohort"):
                if field in operation:
                    updated[field] = deepcopy(operation[field])
            validate_record(updated)
            del working[positions[record_id]]
            working.append(updated)
        elif action == "remove":
            if set(operation) != {"action", "id"} or operation["id"] not in positions:
                raise ValueError("invalid remove")
            del working[positions[operation["id"]]]
        else:
            raise ValueError("unknown action")

    return deepcopy(working)

